//go:build amd64

package floats

// The AVX2+FMA kernel of MulAddRows32 (mulrows32.go), generated by go-asmgen
// (mulrows32_amd64_gen.go) into mulrows32_amd64.s: blocks of 32, 8 and 1 columns, the
// block of dst held in registers across all the rows, for a CPU with the AVX2+FMA of the
// other kernels (hasAVX2FMA, kernels_amd64.go); the portable loop otherwise. The caller
// guarantees rows >= 1, len(dst) >= 1 and the lengths of a and b. No kernel keeps a
// pointer: go:noescape.
//
//go:noescape
func mulAddRows32AVX2(dst, a []float32, lda int, b []float32, ldb int, rows int)

func mulAddRows32(dst, a []float32, lda int, b []float32, ldb int, rows int) {
	if hasAVX2FMA {
		mulAddRows32AVX2(dst, a, lda, b, ldb, rows)
		return
	}
	mulAddRows32Ref(dst, a, lda, b, ldb, rows)
}
